class Order {
  private items: { price: number }[];
  getTotal() { return this.items.reduce((s, i) => s + i.price, 0); }
}
class InvoicePrinter {
  print(order: Order) {
    const items = (order as any).items;
    return items.map(i => i.price).join(', ');
  }
}

class Customer {
  private address: { street: string, city: string };
  getStreet() { return this.address.street; }
  getCity() { return this.address.city; }
}
class ShippingLabel {
  format(customer: Customer) {
    const s = (customer as any).address.street;
    const c = (customer as any).address.city;
    return `${s}, ${c}`;
  }
}

// Version A
class Invoice {
  items: { price: number, tax: number }[];
}
class Report {
  totalExTax(inv: Invoice) {
    return inv.items.reduce((s, i) => s + i.price * (1 - i.tax), 0);
  }
}

