class InvoiceV2 {
  items: { price: number, tax: number }[];
  totalExTax() {
    return this.items.reduce((s, i) => s + i.price * (1 - i.tax), 0);
  }
}
class ReportV2 {
  totalExTax(inv: InvoiceV2) {
    return inv.totalExTax();
  }
}
